begin;
do $$
declare own uuid; guest uuid; g uuid:=gen_random_uuid(); t uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); state jsonb; revision bigint; item uuid; claim uuid; extra uuid;
begin
 select id into own from auth.users where not coalesce(is_anonymous,false) and email_confirmed_at is not null order by created_at limit 1;
 select id into guest from auth.users where not coalesce(is_anonymous,false) and email_confirmed_at is not null and id<>own order by created_at limit 1;
 if guest is null then raise exception 'two confirmed fixture accounts required'; end if;
 perform set_config('request.jwt.claim.sub',own::text,true);
 insert into public.travel_groups(id,owner_id,name) values(g,own,'Temporary potluck test');
 insert into public.trips(id,group_id,organizer_id,name) values(t,g,own,'Temporary potluck test');
 insert into public.trip_access(trip_id,profile_id,role,granted_by) values(t,own,'organizer',own),(t,guest,'participant',own);
 insert into public.group_members(id,group_id,display_name,created_by) values(m,g,'Guest fixture',own);
 insert into public.trip_participants(trip_id,member_id,local_source_id) values(t,m,'guest');
 insert into public.member_profile_links(member_id,profile_id,status,authorized_by) values(m,guest,'active',own);
 insert into public.trip_snapshots(trip_id,payload,revision,updated_by) values(t,'{"trip":{"potluckMode":"potluck","potluckAllowExtras":true},"payments":[{"amountCents":12345}]}',1,own);
 state:=public.get_event_potluck(t);
 if state->>'mode'<>'potluck' then raise exception 'creation preferences lost'; end if;
 state:=public.change_event_potluck(t,'item','{"name":"Salpicão","category":"Acompanhamentos","quantity":2,"unit":"travessas","note":"8 porções"}',1);
 item:=(state->'items'->0->>'id')::uuid; revision:=(state->>'revision')::bigint;
 perform set_config('request.jwt.claim.sub',guest::text,true);
 begin perform public.change_event_potluck(t,'settings','{"mode":"off","allow_extras":true}',revision);raise exception 'guest settings accepted'; exception when others then if sqlerrm<>'access denied' then raise; end if; end;
 state:=public.change_event_potluck(t,'claim',jsonb_build_object('item_id',item,'quantity',1,'scope','family','label','Casal fixture'),revision);
 claim:=(state->'items'->0->'claims'->0->>'id')::uuid;revision:=(state->>'revision')::bigint;
 if not (state->'items'->0->'claims'->0->>'own')::boolean then raise exception 'own claim missing'; end if;
 begin perform public.change_event_potluck(t,'claim',jsonb_build_object('item_id',item,'quantity',3,'scope','person'),revision);raise exception 'overbooking accepted'; exception when others then if sqlerrm<>'not enough remaining' then raise; end if; end;
 begin perform public.change_event_potluck(t,'claim',jsonb_build_object('item_id',item,'quantity',1,'scope','person'),revision-1);raise exception 'stale choice accepted'; exception when others then if sqlerrm<>'list changed' then raise; end if; end;
 state:=public.change_event_potluck(t,'extra','{"name":"Pudim","category":"Sobremesas","quantity":1,"unit":"forma","scope":"person"}',revision);revision:=(state->>'revision')::bigint;
 select id into extra from public.event_potluck_items where trip_id=t and name='Pudim';
 if not exists(select 1 from public.event_potluck_claims where item_id=extra and profile_id=guest) then raise exception 'extra not automatically reserved'; end if;
 perform set_config('request.jwt.claim.sub',own::text,true);
 state:=public.change_event_potluck(t,'settings','{"mode":"mixed","allow_extras":false}',revision);revision:=(state->>'revision')::bigint;
 begin perform public.change_event_potluck(t,'unclaim',jsonb_build_object('id',gen_random_uuid()),revision);raise exception 'foreign claim accepted';exception when others then if sqlerrm<>'access denied' then raise; end if; end;
 begin perform public.change_event_potluck(t,'item',jsonb_build_object('id',item,'name','Salpicão','category','Acompanhamentos','quantity',0.5,'unit','travessas'),revision);raise exception 'reservation truncated';exception when others then if sqlerrm<>'quantity below reserved' then raise; end if; end;
 begin perform public.change_event_potluck(t,'delete',jsonb_build_object('id',item),revision);raise exception 'claimed item deleted';exception when others then if sqlerrm<>'remove reservations first' then raise; end if; end;
 perform set_config('request.jwt.claim.sub',guest::text,true);
 begin perform public.change_event_potluck(t,'extra','{"name":"Outro","category":"Outros","quantity":1,"unit":"unidade","scope":"person"}',revision);raise exception 'strict extras accepted'; exception when others then if sqlerrm<>'only listed items' then raise; end if; end;
 begin perform public.change_event_potluck(t,'claim',jsonb_build_object('item_id',extra,'quantity',1,'scope','person'),revision);raise exception 'strict outside claim accepted';exception when others then if sqlerrm<>'only listed items' then raise; end if; end;
 state:=public.change_event_potluck(t,'delivered',jsonb_build_object('id',claim,'delivered',true),revision);revision:=(state->>'revision')::bigint;
 if not exists(select 1 from public.event_potluck_claims where id=claim and delivered) then raise exception 'delivery missing';end if;
 state:=public.change_event_potluck(t,'unclaim',jsonb_build_object('id',claim),revision);revision:=(state->>'revision')::bigint;
 if exists(select 1 from public.event_potluck_claims where id=claim) then raise exception 'reservation not released';end if;
 if (select payload->'payments' from public.trip_snapshots where trip_id=t)<>'[{"amountCents":12345}]'::jsonb then raise exception 'payments modified';end if;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 begin perform public.get_event_potluck(t);raise exception 'outsider read accepted';exception when others then if sqlerrm<>'access denied' then raise;end if;end;
 perform set_config('request.jwt.claim.sub','',true);
 begin perform public.get_event_potluck(t);raise exception 'anonymous read accepted';exception when others then if sqlerrm<>'access denied' then raise;end if;end;
 if has_table_privilege('authenticated','public.event_potluck_claims','INSERT') then raise exception 'direct writes exposed';end if;
 if has_function_privilege('anon','public.change_event_potluck(uuid,text,jsonb,bigint)','EXECUTE') then raise exception 'anonymous writes exposed';end if;
end $$;
rollback;
